// widget.h - Interface, no implementation details
#include <memory>

class Widget {
public:
    Widget();
    ~Widget(); // Destructor must be declared
    Widget(Widget&&) noexcept; // Move operations also declared
    Widget& operator=(Widget&&) noexcept;

    // Copy operations can be declared and defined as well
    Widget(const Widget& other);
    Widget& operator=(const Widget& other);

private:
    struct Impl; // Forward-declare the implementation struct
    std::unique_ptr<Impl> pImpl; // Use smart pointer for Pimpl
};

// widget.cpp - Implementation details are hidden here
#include "widget.h" 
#include <string>
#include <vector>

// Full definition of the implementation struct
struct Widget::Impl {
    std::string name;
    std::vector<double> data;
};

// Destructor defined where Impl is a complete type
Widget::Widget() : pImpl(std::make_unique<Impl>()) {}
Widget::~Widget() = default; // OK: Impl is complete, default is correct
Widget::Widget(Widget&&) noexcept = default;
Widget& Widget::operator=(Widget&&) noexcept = default;
